#!/usr/bin/env bash
# Doc développeur : purge des souhaits d'un mineur, extraits recalés.
# Prérequis : apply-fix-circuit-parent-tuto.sh.
# Usage (racine du repo) : bash apply-docs-circuit-parent-tuto.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/legal/donnees-personnelles.mdx" 2>/dev/null | grep -qF "Les souhaits d’un mineur restés sans réponse"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "adminUsersDroitImageMineur" "apps/web/src/features/tours/tour.registry.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-circuit-parent-tuto.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/auth/fermer-une-session.mdx" "apps/web/content/docs/dev/etude-de-cas/un-tutoriel-en-donnees.mdx" "apps/web/content/docs/dev/legal/donnees-personnelles.mdx")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Les souhaits d’un mineur restés sans réponse" "apps/web/content/docs/dev/legal/donnees-personnelles.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/content/docs/dev/auth/fermer-une-session.mdx', '',
    '')
