sub('apps/web/content/docs/dev/legal/donnees-personnelles.mdx', 'ICBmaWxlcGF0aD0icGFja2FnZXMvYmFja2VuZC9zcmMvbW9kdWxlcy9wcml2YWN5L3JldGVudGlvbi5zZXJ2aWNlLnRzIgogIGZpbGVuYW1lPSJyZXRlbnRpb24uc2VydmljZS50cyIKICBzbmlwcGV0UmFuZ2U9IjYxLTY3IgogIHNuaXBwZXRIaWdobGlnaHQ9IjUiCiAgc25pcHBldFRpdGxlPSJMZXMgY29tcHRlcyDDoCBleGFtaW5lciIK',
    'ICBmaWxlcGF0aD0icGFja2FnZXMvYmFja2VuZC9zcmMvbW9kdWxlcy9wcml2YWN5L3JldGVudGlvbi5zZXJ2aWNlLnRzIgogIGZpbGVuYW1lPSJyZXRlbnRpb24uc2VydmljZS50cyIKICBzbmlwcGV0UmFuZ2U9Ijc2LTgyIgogIHNuaXBwZXRIaWdobGlnaHQ9IjUiCiAgc25pcHBldFRpdGxlPSJMZXMgY29tcHRlcyDDoCBleGFtaW5lciIK')
